RED.systemInfo = (function() {

    var updateInterval = 5000; // 5秒更新一次
    var intervalId = null;
    var widgetElement = null;
    var lastData = null;

    function formatBytes(bytes) {
        if (bytes === 0) return '0 B';
        const k = 1024;
        const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
    }

    function formatPercentage(used, total) {
        if (total === 0) return '0%';
        return Math.round((used / total) * 100) + '%';
    }

    function updateSystemInfo() {
        $.ajax({
            headers: {
                "Accept": "application/json"
            },
            cache: false,
            url: 'diagnostics',
            success: function(data) {
                lastData = data;
                renderSystemInfo(data);
            },
            error: function() {
                // API调用失败时显示错误状态
                if (widgetElement) {
                    widgetElement.html('<span class="system-info-error">系统信息不可用</span>');
                }
            }
        });
    }

    function renderSystemInfo(data) {
        if (!widgetElement || !data) return;

        var cpuUsage = 'N/A';
        var memoryUsage = 'N/A';
        var systemLoad = 'N/A';

        // 计算CPU使用率 (简化版本，实际可能需要更复杂的计算)
        if (data.os && data.os.loadavg && Array.isArray(data.os.loadavg) && data.os.loadavg.length > 0) {
            systemLoad = data.os.loadavg[0].toFixed(2);
        }

        // 计算内存使用率
        if (data.os && data.os.totalmem && data.os.freemem !== undefined) {
            var usedMem = data.os.totalmem - data.os.freemem;
            memoryUsage = formatPercentage(usedMem, data.os.totalmem);
        }

        // Node.js进程内存使用
        var nodeMemory = 'N/A';
        if (data.nodejs && data.nodejs.memoryUsage) {
            var nodeMem = data.nodejs.memoryUsage;
            nodeMemory = formatBytes(nodeMem.heapUsed);
        }

        // 更新显示内容
        var html = '<div class="system-info-container">';
        html += '<span class="system-info-item" title="系统负载: ' + systemLoad + '">CPU: ' + systemLoad + '</span>';
        html += '<span class="system-info-item" title="内存使用: ' + memoryUsage + '">RAM: ' + memoryUsage + '</span>';
        html += '<span class="system-info-item" title="Node.js内存: ' + nodeMemory + '">Node: ' + nodeMemory + '</span>';
        html += '</div>';

        widgetElement.html(html);
    }

    function showDetailedInfo() {
        if (!lastData) {
            RED.notify("系统信息不可用", "error");
            return;
        }

        // 构建详细信息HTML
        var details = '<div class="system-info-details">';
        details += '<h3>系统信息</h3>';

        if (lastData.os) {
            details += '<div class="info-section">';
            details += '<h4>操作系统</h4>';
            details += '<p><strong>平台:</strong> ' + (lastData.os.platform || 'N/A') + '</p>';
            details += '<p><strong>架构:</strong> ' + (lastData.os.arch || 'N/A') + '</p>';
            details += '<p><strong>类型:</strong> ' + (lastData.os.type || 'N/A') + '</p>';
            details += '<p><strong>版本:</strong> ' + (lastData.os.version || 'N/A') + '</p>';
            details += '<p><strong>总内存:</strong> ' + (lastData.os.totalmem ? formatBytes(lastData.os.totalmem) : 'N/A') + '</p>';
            details += '<p><strong>可用内存:</strong> ' + (lastData.os.freemem !== undefined ? formatBytes(lastData.os.freemem) : 'N/A') + '</p>';
            if (lastData.os.loadavg && Array.isArray(lastData.os.loadavg)) {
                details += '<p><strong>负载平均值:</strong> ' + lastData.os.loadavg.map(x => x.toFixed(2)).join(', ') + '</p>';
            }
            details += '<p><strong>运行时间:</strong> ' + (lastData.os.uptime ? Math.round(lastData.os.uptime / 3600) + ' 小时' : 'N/A') + '</p>';
            details += '</div>';
        }

        if (lastData.nodejs) {
            details += '<div class="info-section">';
            details += '<h4>Node.js</h4>';
            details += '<p><strong>版本:</strong> ' + (lastData.nodejs.version || 'N/A') + '</p>';
            if (lastData.nodejs.memoryUsage) {
                var mem = lastData.nodejs.memoryUsage;
                details += '<p><strong>堆内存使用:</strong> ' + formatBytes(mem.heapUsed) + ' / ' + formatBytes(mem.heapTotal) + '</p>';
                details += '<p><strong>外部内存:</strong> ' + formatBytes(mem.external) + '</p>';
                details += '<p><strong>RSS内存:</strong> ' + formatBytes(mem.rss) + '</p>';
            }
            details += '</div>';
        }

        details += '</div>';

        // 使用jQuery UI dialog显示详细信息
        var dialog = $('<div id="system-info-dialog" class="hide"></div>').html(details);
        dialog.appendTo("#red-ui-editor").dialog({
            modal: true,
            autoOpen: false,
            width: 500,
            height: 400,
            resizable: false,
            classes: {
                "ui-dialog": "red-ui-editor-dialog",
                "ui-dialog-titlebar-close": "hide",
                "ui-widget-overlay": "red-ui-editor-dialog"
            },
            title: "系统详细信息",
            buttons: [
                {
                    text: "关闭",
                    click: function() {
                        $(this).dialog("close");
                    }
                }
            ],
            open: function( event, ui ) {
                RED.keyboard.disable();
            },
            close: function(e) {
                RED.keyboard.enable();
                $(this).dialog('destroy').remove();
            }
        }).dialog("open");
    }

    function init() {
        // 创建控件元素
        widgetElement = $('<div id="red-ui-system-info-widget"></div>');

        // 添加点击事件显示详细信息
        widgetElement.on('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            showDetailedInfo();
        });

        // 添加到状态栏
        RED.statusBar.add({
            id: "red-ui-system-info",
            align: "right",
            element: widgetElement
        });

        // 初始加载系统信息
        updateSystemInfo();

        // 设置定时更新
        intervalId = setInterval(updateSystemInfo, updateInterval);
    }

    function destroy() {
        if (intervalId) {
            clearInterval(intervalId);
            intervalId = null;
        }
        if (widgetElement) {
            widgetElement.remove();
            widgetElement = null;
        }
    }

    return {
        init: init,
        destroy: destroy,
        updateInterval: function(newInterval) {
            if (newInterval && newInterval > 0) {
                updateInterval = newInterval;
                if (intervalId) {
                    clearInterval(intervalId);
                    intervalId = setInterval(updateSystemInfo, updateInterval);
                }
            }
            return updateInterval;
        }
    };
})();